'use strict';

// MAIN //

/**
* Resolves the number of output rows and the starting row offset for a convolution matrix.
*
* @private
* @param {string} mode - convolution mode
* @param {NonNegativeInteger} m - number of indexed elements in `x`
* @param {NonNegativeInteger} N - number of columns in the output matrix
* @param {Array} out - output array for storing the result
* @returns {Array} output array where `out[0]` is the number of rows and `out[1]` is the starting row offset
*
* @example
* var out = [ 0, 0 ];
* resolveMode( 'full', 3, 3, out );
* // out => [ 5, 0 ]
*
* @example
* var out = [ 0, 0 ];
* resolveMode( 'same', 3, 3, out );
* // out => [ 3, 1 ]
*
* @example
* var out = [ 0, 0 ];
* resolveMode( 'valid', 3, 5, out );
* // out => [ 3, 2 ]
*/
function resolveMode( mode, m, N, out ) {
	var d;
	if ( mode === 'full' ) {
		out[ 0 ] = m + N - 1;
		out[ 1 ] = 0;
	} else if ( mode === 'same' ) {
		out[ 0 ] = ( m >= N ) ? m : N;
		d = ( m < N ) ? m : N;
		out[ 1 ] = ( ( d - 1 ) / 2 ) | 0;
	} else { // mode === 'valid'
		d = m - N;
		out[ 0 ] = ( ( d < 0 ) ? -d : d ) + 1;
		d = ( m < N ) ? m : N;
		out[ 1 ] = d - 1;
	}
	return out;
}


// EXPORTS //

module.exports = resolveMode;
